import { z } from "zod";

/**
 * Response schemas for the core domain entities.
 *
 * These exist so the API's *outputs* are described by the same kind of
 * checked source as its inputs. Until now only request bodies had zod schemas,
 * which meant the OpenAPI document could describe what the API accepted but had
 * nothing truthful to say about what it returned — so every consumer, including
 * our own frontend, hand-declared the response types and they drifted.
 *
 * Deriving frontend types from these (see frontend/src/types/api.generated.ts,
 * regenerated by `npm run generate:types`) makes a rename on the server a
 * compile error in the client rather than a runtime undefined.
 *
 * Two deliberate choices:
 *
 *   - `_id` is `z.string()`, not an ObjectId type. By the time JSON reaches a
 *     client the id is a string, and typing it as one prevents the classic
 *     `ObjectId cannot be assigned to string` mismatch.
 *   - `createdAt`/`updatedAt` are ISO strings, not `Date`. JSON has no Date.
 *
 * Fields are `.passthrough()` where the entity is returned with populated
 * references, because a strict schema would report a false error for a field
 * the server genuinely adds.
 */

/** Mongo ObjectId as it appears in JSON. */
export const objectId = z.string().regex(/^[a-f0-9]{24}$/i, "Not a Mongo id");

export const isoDateTime = z.string().describe("ISO 8601 timestamp");

// ── Shared sub-documents ────────────────────────────────────────────────────

/**
 * A user as embedded in another entity's response (never the full document).
 *
 * Note the id: a populated reference exposes `_id`, while `loginUser` returns
 * `id`. Both exist in this API, which is why the auth schema below is separate.
 */
export const userRefSchema = z
  .object({
    _id: objectId,
    name: z.string(),
    profileImageUrl: z.string().optional(),
    role: z.enum(["patient", "doctor", "staff", "admin"]).optional(),
    phone: z.string().optional(),
    email: z.string().optional(),
  })
  .passthrough();

/**
 * A doctor profile as the directory returns it.
 *
 * Every name here is plural where the intuitive guess would be singular —
 * `specializations`, `qualifications`, `languagesSpoken`, `experienceYears` —
 * verified against a live response rather than read off, because the first
 * draft used `specialization`, `qualification` and `experience` and would have
 * been wrong on all three.
 */
export const doctorProfileSchema = z
  .object({
    specializations: z.array(z.string()).optional(),
    qualifications: z.array(z.string()).optional(),
    languagesSpoken: z.array(z.string()).optional(),
    experienceYears: z.number().optional(),
    consultationFee: z.number().optional(),
  })
  .passthrough();

/** An entry in `GET /user/doctors`. */
export const doctorDirectoryEntrySchema = z
  .object({
    _id: objectId,
    name: z.string(),
    profileImageUrl: z.string().optional(),
    doctorProfile: doctorProfileSchema.optional(),
    totalReviews: z.number().int().nonnegative().optional(),
    avgRating: z.number().min(0).max(5).optional(),
    /** Review count keyed by star, 1..5. */
    ratingDistribution: z.record(z.string(), z.number().int().nonnegative()).optional(),
  })
  .passthrough();

// ── Authentication ──────────────────────────────────────────────────────────

/**
 * What login returns.
 *
 * Note `id`, not `_id`, and no `email`: login deliberately returns the minimum
 * the app shell needs. There is also no `refreshToken` in the body — it is an
 * httpOnly cookie, so JavaScript cannot read it.
 */
export const authSessionSchema = z.object({
  accessToken: z.string(),
  user: z.object({
    id: z.string(),
    name: z.string(),
    role: z.enum(["patient", "doctor", "staff", "admin"]),
    profileImageUrl: z.string(),
    emailVerified: z.boolean(),
  }),
});

/** What `POST /auth/refresh` returns — the access token, and nothing else. */
export const refreshedAccessTokenSchema = z.object({
  accessToken: z.string(),
});

// ── Review ──────────────────────────────────────────────────────────────────

export const reviewSchema = z
  .object({
    _id: objectId,
    /**
     * Populated with `{ _id, name, profileImageUrl }` by the list endpoint, so
     * it is an embedded user here rather than an id — while `doctorId` stays a
     * bare id. That asymmetry is real (only one side is populated to keep the
     * response small) and is why the types cannot be simplified by eye.
     */
    patientId: z
      .object({
        _id: objectId,
        name: z.string(),
        profileImageUrl: z.string().optional(),
      })
      .passthrough(),
    doctorId: objectId,
    rating: z.number().int().min(1).max(5),
    /** Defaults to "" in the schema, so always present. */
    comment: z.string(),
    createdAt: isoDateTime,
    updatedAt: isoDateTime,
  })
  .passthrough();

/**
 * Per-doctor totals, computed by the list endpoint so the UI does not have to
 * join against the doctors endpoint. Note `avgRating` and `distribution`: the
 * obvious names would be `averageRating` and `buckets`, and the frontend used to
 * guess — this schema pins the real ones.
 */
export const reviewSummarySchema = z.object({
  avgRating: z.number().min(0).max(5),
  totalReviews: z.number().int().nonnegative(),
  /** Review count per star, keyed 1..5. */
  distribution: z.record(z.string(), z.number().int().nonnegative()),
});

export const reviewListResponseSchema = z.object({
  reviews: z.array(reviewSchema),
  summary: reviewSummarySchema,
  /**
   * Whether the signed-in patient may rate this doctor. Computed up front from
   * the same completed-visit rule upsertReview enforces, so the UI can explain
   * why the form is unavailable instead of letting a patient fill it in and hit
   * a 403.
   */
  canReview: z.boolean(),
  myReview: reviewSchema.nullable(),
});

// ── Report ──────────────────────────────────────────────────────────────────

/**
 * A file inside a report.
 *
 * The storage fields are genuinely optional and mutually exclusive: an image
 * has `url`/`publicId` (Cloudinary), a PDF has `storageId` (GridFS). That split
 * is why this shape has three optional fields rather than one required URL —
 * and it is the sort of thing a hand-written interface tends to get wrong.
 */
export const reportFileSchema = z.object({
  url: z.string().optional(),
  publicId: z.string().optional(),
  storageId: z.string().optional(),
  storage: z.enum(["cloudinary", "gridfs"]).optional(),
  name: z.string(),
  mimeType: z.string(),
  size: z.number(),
  resourceType: z.string().optional(),
});

export const reportSchema = z
  .object({
    _id: objectId,
    patientId: userRefSchema,
    uploadedBy: userRefSchema,
    title: z.string(),
    category: z.enum(["lab", "imaging", "test", "other"]),
    description: z.string().optional(),
    consultationId: objectId.optional(),
    files: z.array(reportFileSchema),
    createdAt: isoDateTime,
    updatedAt: isoDateTime,
  })
  .passthrough();

/**
 * `GET /report` returns `{ count, reports }`.
 *
 * This was previously declared as a bare array, which was wrong — and wrong in
 * the way that hides itself, because nothing ever parsed a real response
 * against it. That is the reason every schema here is checked against a live
 * call rather than trusted because it looks right.
 */
export const reportListSchema = z.object({
  count: z.number().int().nonnegative(),
  reports: z.array(reportSchema),
});

// ── Notification ────────────────────────────────────────────────────────────

/**
 * Mirrors NOTIFICATION_TYPES in db/models/notification.model.ts.
 *
 * Worth stating plainly: an earlier draft of this file invented a plausible
 * looking set (`appointment`, `report`, `system`, …) with `userId`/`message`/
 * `read` fields. The real model has always used `recipientId`/`body`/`readAt`
 * and a much shorter type list. The invented version would have typechecked
 * happily and then rejected every real notification — which is why these
 * schemas are now verified against live responses in tests/api/responseSchemas.test.ts
 * rather than trusted because they look right.
 */
export const notificationTypeSchema = z.enum([
  "leave-conflict",
  "appointment-status",
  "appointment-rescheduled",
  "follow-up-due",
]);

export const notificationSchema = z
  .object({
    _id: objectId,
    recipientId: objectId,
    type: notificationTypeSchema,
    title: z.string(),
    body: z.string(),
    link: z.string().optional(),
    appointmentId: objectId.optional(),
    /** null until read; the field is always present. */
    readAt: z.string().nullable(),
    createdAt: isoDateTime,
  })
  .passthrough();

// ── Clinic ──────────────────────────────────────────────────────────────────

export const clinicDayHoursSchema = z.object({
  /** Weekday as a 0-6 index (0 = Sunday), matching the mongoose model. */
  day: z.number().int().min(0).max(6),
  isOpen: z.boolean(),
  slots: z.array(z.string()).optional(),
});

/**
 * What the public settings endpoint actually returns.
 *
 * This is deliberately NOT the ClinicSettings document. That one holds `_id`,
 * `slots` and `workingHours` for internal use; the public endpoint projects a
 * narrower, deliberately safe view — contact details, opening hours, and a
 * `today` block carrying the live open/closed state.
 *
 * Worth stating because the first draft of this schema described the internal
 * document, which looked plausible and failed on the first field.
 */
export const publicClinicSettingsSchema = z
  .object({
    clinicName: z.string(),
    address: z.string(),
    phone: z.string(),
    email: z.string(),
    about: z.string(),
    /** How far ahead a patient may still cancel without penalty. */
    cancellationWindowMinutes: z.number(),
    hours: z.array(clinicDayHoursSchema),
    today: z
      .object({
        day: z.number().int().min(0).max(6),
        isOpen: z.boolean(),
        slots: z.array(z.string()),
        isOpenNow: z.boolean(),
        opensAt: z.string().nullable(),
        closesAt: z.string().nullable(),
        nextChangeAt: z.string().nullable(),
      })
      .passthrough(),
  })
  .passthrough();

export const clinicBlockoutSchema = z
  .object({
    _id: objectId,
    date: z.string(),
    endDate: z.string().optional(),
    reason: z.string().optional(),
    doctorId: objectId.optional(),
    scope: z.enum(["clinic", "doctor"]).optional(),
    createdAt: isoDateTime.optional(),
  })
  .passthrough();

// ── Directory ───────────────────────────────────────────────────────────────

/**
 * A user as the *admin* directory returns it: credentials stripped, plus
 * whatever role-specific profile the role carries.
 *
 * `role` is required here because getAllUsers selects it explicitly. The patient
 * directory does not — its projection omits `role` entirely (every row is a
 * patient, so the field would be redundant), which is why
 * `patientDirectoryEntrySchema` below treats it as optional.
 */
export const userSummarySchema = z
  .object({
    _id: objectId,
    name: z.string(),
    email: z.string(),
    phone: z.string(),
    role: z.enum(["patient", "doctor", "staff", "admin"]),
    gender: z.string().optional(),
    dateOfBirth: z.string().optional(),
    bloodGroup: z.string().optional(),
    profileImageUrl: z.string().optional(),
    isActive: z.boolean().optional(),
    /** Present on doctor profiles only. Plural field names — see doctorProfileSchema. */
    doctorProfile: doctorProfileSchema.optional(),
  })
  .passthrough();

/**
 * The patient directory's narrower projection — no `role`, no `isActive`,
 * because the query already filtered on both and the UI never needed them.
 */
export const patientDirectoryEntrySchema = userSummarySchema.omit({
  role: true,
  isActive: true,
});

/** A dependent, which has no login of its own and therefore no email. */
export const familyMemberSchema = z
  .object({
    _id: objectId,
    name: z.string(),
    phone: z.string(),
    gender: z.string().optional(),
    dateOfBirth: z.string().optional(),
    bloodGroup: z.string().optional(),
    accountType: z.literal("dependent").optional(),
    shareCode: z.string().optional(),
    guardians: z.array(objectId).optional(),
  })
  .passthrough();

/** `{ notifications, unreadCount }` as the notification list endpoint returns. */
export const notificationListSchema = z.array(notificationSchema);

// ── Leave ───────────────────────────────────────────────────────────────────

export const leaveRecordSchema = z
  .object({
    _id: objectId,
    doctorId: objectId,
    fromDate: z.string(),
    toDate: z.string(),
    reason: z.string().optional(),
    status: z.enum(["pending", "approved", "rejected"]),
    createdAt: isoDateTime.optional(),
  })
  .passthrough();

// ── Appointment ─────────────────────────────────────────────────────────────

export const appointmentStatusSchema = z.enum([
  "pending",
  "arrived",
  "completed",
  "cancelled",
  "no-show",
]);

export const appointmentSchema = z
  .object({
    _id: objectId,
    /**
     * References are populated on some endpoints and left as bare ids on others
     * (the data export, for instance). Both are accepted deliberately rather
     * than pretending the shape is uniform.
     */
    patientId: z.union([objectId, userRefSchema]).optional(),
    doctorId: z.union([objectId, userRefSchema]).optional(),
    appointmentDate: z.string(),
    timeSlot: z.string(),
    durationInMinutes: z.number().optional(),
    status: appointmentStatusSchema,
    consultationType: z.string().optional(),
    /** Null until the patient is checked in — present, not merely optional. */
    checkedInAt: z.string().nullable().optional(),
    checkedInBy: z.union([objectId, userRefSchema]).nullable().optional(),
    cancellationReason: z.string().optional(),
    needsReschedule: z.boolean().optional(),
    rescheduleSuggestions: z.array(z.unknown()).optional(),
    reminderEmailAt: z.string().nullable().optional(),
    intakeDetails: z.record(z.string(), z.unknown()).optional(),
    createdAt: isoDateTime.optional(),
    updatedAt: isoDateTime.optional(),
  })
  .passthrough();

// ── Check-in ────────────────────────────────────────────────────────────────

/**
 * What `POST /appointment/check-in` returns.
 *
 * Three fields here are not guessable and were previously hand-declared on the
 * frontend, where nothing could catch them drifting:
 *
 *   - `alreadyCheckedIn` — the endpoint is idempotent, so scanning the same
 *     ticket twice is success with a different message, not an error.
 *   - `staleDate` / `slotMismatch` — a ticket printed before a reschedule still
 *     checks the patient in, flagged so the desk knows it is reading old paper.
 */
export const checkInResultSchema = z.object({
  appointment: z
    .object({
      _id: objectId,
      /** UTC-midnight anchor, ISO 8601. */
      appointmentDate: z.string(),
      timeSlot: z.string(),
      consultationType: z.string().optional(),
      status: appointmentStatusSchema,
      /** Null when the appointment had already arrived. */
      checkedInAt: z.string().nullable(),
      patient: z.object({ _id: objectId, name: z.string() }).passthrough(),
      doctor: z.object({ _id: objectId, name: z.string() }).passthrough(),
    })
    .passthrough(),
  /** True when the ticket was scanned again after the patient was already in. */
  alreadyCheckedIn: z.boolean(),
  /** The printed date is not the appointment's current date. */
  staleDate: z.boolean(),
  /** The printed slot is not the appointment's current slot. */
  slotMismatch: z.boolean(),
});

// ── Envelope helpers ────────────────────────────────────────────────────────

/**
 * NOTE: the `{ success, message, data }` envelope is assembled in
 * openapi/generate.ts rather than here.
 *
 * It was briefly duplicated here as `envelope()`, and nothing ever used it —
 * the generator wraps each payload in its own `responseEnvelope`, which also
 * has to know about the optional `message`. Dead code that reads like a live
 * abstraction is worse than no abstraction, so it is gone rather than left for
 * someone to pick up and wire to the wrong half.
 */

/** Pagination block, as the paginated list endpoints return it. */
export const paginationSchema = z.object({
  totalItems: z.number().int().nonnegative(),
  currentPage: z.number().int().positive(),
  totalPages: z.number().int().nonnegative(),
  hasNextPage: z.boolean(),
  hasPrevPage: z.boolean(),
});

/** `{ count, appointments }` — the queue-shaped list endpoints. */
export const appointmentQueueSchema = z.object({
  count: z.number().int().nonnegative(),
  appointments: z.array(appointmentSchema),
});

/** `GET /appointment` adds pagination to the queue shape. */
export const appointmentPageSchema = appointmentQueueSchema.extend({
  pagination: paginationSchema,
});

/**
 * `GET /appointment/slots` returns slot *states*, not bare slot labels.
 *
 * `GET /appointment/available-slots` returns plain strings. Two adjacent
 * endpoints with different payload shapes and similar names — another thing a
 * guess would have got wrong.
 */
export const slotStateSchema = z.object({
  timeSlot: z.string(),
  /** e.g. "free" | "held" | "held-by-you" | "taken". */
  state: z.string(),
});

/** `{ shareCode }`. */
export const shareCodeSchema = z.object({ shareCode: z.string() });

// ── Consultation ────────────────────────────────────────────────────────────

/**
 * A prescription line.
 *
 * The remedy field is `remedyName`, not `drug` — homeopathic prescriptions name
 * a remedy, and this schema originally guessed `drug` and would have been wrong.
 * Caught because the fixture failed to save, not because anyone read the model.
 *
 * `potency` defaults to null, so it is present but nullable.
 */
export const prescriptionSchema = z
  .object({
    _id: objectId.optional(),
    remedyName: z.string(),
    potency: z.string().nullable().optional(),
    dosage: z.string(),
    durationInDays: z.number(),
  })
  .passthrough();

/**
 * A consultation as `GET /consultation/history/:patientId` returns it, where
 * `appointmentId` is populated to `{ _id, appointmentDate, consultationType }`.
 * The "latest" endpoint returns the same record with bare string ids, so this
 * schema stays permissive on those two fields.
 */
/**
 * A populated reference of unknown shape.
 *
 * Consultations populate `appointmentId` to `{ _id, appointmentDate,
 * consultationType }`, which is neither a bare id nor a user reference, so the
 * specific schemas cannot describe it. `userRefSchema` rejected it outright
 * when it was tried here.
 */
const populatedRefSchema = z.object({ _id: objectId }).passthrough();

export const consultationHistoryEntrySchema = z
  .object({
    _id: objectId,
    appointmentId: z.union([objectId, populatedRefSchema]).optional(),
    patientId: z.union([objectId, userRefSchema]).optional(),
    doctorId: z.union([objectId, userRefSchema]).optional(),
    chiefComplaintDetails: z.record(z.string(), z.unknown()).optional(),
    physicalGenerals: z.record(z.string(), z.unknown()).optional(),
    mentalGenerals: z.string().optional(),
    pastMedicalHistory: z.string().optional(),
    diagnosis: z.string().optional(),
    prescriptions: z.array(prescriptionSchema).optional(),
    doctorNotes: z.string().optional(),
    followUpDate: z.string().optional(),
    followUpStatus: z.string().optional(),
    followUpReminderSentAt: z.string().nullable().optional(),
    createdAt: isoDateTime,
    updatedAt: isoDateTime,
  })
  .passthrough();

export const medicalHistorySchema = z.object({
  count: z.number().int().nonnegative(),
  history: z.array(consultationHistoryEntrySchema),
});

/** An entry in `GET /consultation/follow-ups`. */
export const followUpSchema = z
  .object({
    _id: objectId,
    appointmentId: objectId,
    doctorId: userRefSchema.optional(),
    patientId: userRefSchema.optional(),
    diagnosis: z.string().optional(),
    followUpDate: z.string().optional(),
    followUpStatus: z.string().optional(),
    createdAt: isoDateTime.optional(),
  })
  .passthrough();

// ── User self-service ───────────────────────────────────────────────────────

/**
 * `GET /user/me` — the signed-in user's own document, credentials stripped.
 *
 * Broader than `userSummarySchema` because a user reading their own record gets
 * the real profile, not the directory projection.
 */
export const ownProfileSchema = z
  .object({
    _id: objectId,
    name: z.string(),
    email: z.string(),
    phone: z.string(),
    role: z.enum(["patient", "doctor", "staff", "admin"]),
    accountType: z.string().optional(),
    gender: z.string().optional(),
    dateOfBirth: z.string().optional(),
    bloodGroup: z.string().optional(),
    profileImageUrl: z.string().optional(),
    shareCode: z.string().optional(),
    guardians: z.array(objectId).optional(),
    isActive: z.boolean().optional(),
    emailVerified: z.boolean().optional(),
    doctorProfile: doctorProfileSchema.optional(),
    createdAt: isoDateTime.optional(),
    updatedAt: isoDateTime.optional(),
  })
  .passthrough();

/** `GET /user/me/export` — a portability bundle of everything held about you. */
export const dataExportSchema = z.object({
  exportedAt: isoDateTime,
  exportedBy: z.object({
    id: z.string(),
    name: z.string(),
    email: z.string(),
    role: z.string(),
  }),
  profile: ownProfileSchema,
  familyMembers: z.array(familyMemberSchema).optional(),
  appointments: z.array(appointmentSchema).optional(),
  consultations: z.array(consultationHistoryEntrySchema).optional(),
  notifications: z.array(notificationSchema).optional(),
  reviews: z.array(reviewSchema).optional(),
});

// ── Administration ──────────────────────────────────────────────────────────

/** `GET /admin/stats` — dashboard counters. */
export const adminStatsSchema = z.object({
  totalPatients: z.number().int().nonnegative(),
  totalDoctors: z.number().int().nonnegative(),
  totalStaff: z.number().int().nonnegative(),
  totalAppointments: z.number().int().nonnegative(),
  todaysAppointments: z.number().int().nonnegative(),
  pendingAppointments: z.number().int().nonnegative(),
  completedConsultations: z.number().int().nonnegative(),
});

/** `GET /admin/analytics`. */
export const adminAnalyticsSchema = z.object({
  appointmentsByDoctor: z
    .array(
      z.object({
        doctorId: objectId,
        doctorName: z.string(),
        total: z.number().int().nonnegative(),
        statuses: z.record(z.string(), z.number().int().nonnegative()),
      }),
    )
    .optional(),
  statusRates: z
    .array(z.object({ status: z.string(), count: z.number().int().nonnegative() }))
    .optional(),
  totalAppointments30d: z.number().int().nonnegative().optional(),
  newPatientsByMonth: z
    .array(
      z.object({
        month: z.string(),
        label: z.string(),
        count: z.number().int().nonnegative(),
      }),
    )
    .optional(),
});

/** One row of the PHI access log. */
export const accessLogEntrySchema = z
  .object({
    _id: objectId,
    actorId: objectId,
    actorRole: z.string(),
    actorName: z.string().optional(),
    patientId: objectId,
    resource: z.enum([
      "consultation",
      "report",
      "medical-history",
      "appointment",
      "patient-profile",
    ]),
    resourceId: objectId.optional(),
    action: z.enum(["read", "create", "update", "delete", "export"]),
    route: z.string().optional(),
    ip: z.string().optional(),
    createdAt: isoDateTime,
  })
  .passthrough();

/** The two audit list endpoints share one shape. */
export const accessLogPageSchema = z.object({
  count: z.number().int().nonnegative(),
  entries: z.array(accessLogEntrySchema),
});